{
  "findings": [
    {
      "check_id": "CKV_GCP_11",
      "title": "Cloud SQL database instance is open to the world (0.0.0.0/0)",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The authorized_networks block includes '0.0.0.0/0', which allows connections from any IP address on the internet, exposing the database to unauthorized access and attacks."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "SSL/TLS encryption for incoming connections is disabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "require_ssl is set to false, meaning data in transit between clients and the database is not encrypted, risking interception of sensitive information."
    },
    {
      "check_id": "CKV_GCP_51",
      "title": "PostgreSQL log_checkpoints flag is not enabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The log_checkpoints flag is missing or not set to 'on', preventing the logging of checkpoint events which are crucial for monitoring database performance and recovery points."
    },
    {
      "check_id": "CKV_GCP_52",
      "title": "PostgreSQL log_connections flag is not enabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The log_connections flag is missing or not set to 'on', preventing the logging of successful connection attempts, which hinders audit trails and security monitoring."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "PostgreSQL log_disconnections flag is not enabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The log_disconnections flag is missing or not set to 'on', preventing the logging of session terminations, which reduces visibility into user activity duration and anomalies."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "PostgreSQL log_lock_waits flag is not enabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The log_lock_waits flag is missing or not set to 'on', preventing the logging of lock wait times, which makes it difficult to diagnose performance issues caused by contention."
    },
    {
      "check_id": "CKV2_GCP_13",
      "title": "PostgreSQL log_duration flag is not enabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The log_duration flag is missing or not set to 'on', preventing the logging of statement execution durations, which is essential for identifying slow queries and performance bottlenecks."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_duration\"\n      value = \"on\"\n    }\n  }\n  deletion_protection = false\n}",
  "fix_summary": "Removed the public '0.0.0.0/0' authorized network entry to restrict access to internal networks only. Enabled SSL/TLS encryption by setting require_ssl to true. Added several critical PostgreSQL logging flags (log_checkpoints, log_connections, log_disconnections, log_lock_waits, log_duration) to enhance auditability and performance monitoring."
}
